          vapour+=mistBank(eye,aim,reach,vec3(365.,4.,-61.)+drift*.80,vec3(253.,23.,141.))*.0055;
          vapour+=mistBank(eye,aim,reach,vec3(468.,22.,57.)+drift*.54,vec3(315.,31.,166.))*.0036;
          vapour+=mistBank(eye,aim,reach,vec3(68.,3.,62.)+drift*.58,vec3(472.,25.,171.))*.0024;
          vapour+=mistBank(eye,aim,reach,vec3(-342.,8.,-33.)+drift*.69,vec3(305.,19.,113.))*.0034;
          vapour+=mistBank(eye,aim,reach,vec3(1.,-11.,-53.)+drift*.64,vec3(236.,23.,145.))*.0058;
